# Let me think about connected components of 7s - are "isolated" 7s the ones that change?
# Or are the "middle" 7s in a component that change?

def find_connected_7_regions(grid):
    visited = set()
    regions = []
    rmax, cmax = len(grid), len(grid[0])

    for r in range(rmax):
        for c in range(cmax):
            if grid[r][c] == 7 and (r, c) not in visited:
                region = []
                stack = [(r, c)]
                while stack:
                    cr, cc = stack.pop()
                    if (cr, cc) in visited:
                        continue
                    visited.add((cr, cc))
                    region.append((cr, cc))
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < rmax and 0 <= nc < cmax and grid[nr][nc] == 7 and (nr, nc) not in visited:
                            stack.append((nr, nc))
                regions.append(region)

    return regions

