def is_rectangularly_enclosed(grid, r, c):
    """Check if cell is inside a rectangle of 8s"""
    rmax, cmax = len(grid), len(grid[0])

    # Look for 8s at distance in all 4 directions
    # N-S direction
    n_dist = 0
    while r - n_dist > 0 and grid[r - n_dist][c] != 8:
        n_dist += 1
    s_dist = 0
    while r + s_dist < rmax and grid[r + s_dist][c] != 8:
        s_dist += 1

    # W-E direction  
    w_dist = 0
    while c - w_dist > 0 and grid[r][c - w_dist] != 8:
        w_dist += 1
    e_dist = 0
    while c + e_dist < cmax and grid[r][c + e_dist] != 8:
        e_dist += 1

    # If there's 8 in all 4 directions, the cell is "enclosed"
    return (n_dist > 0 and s_dist > 0 and w_dist > 0 and e_dist > 0)

